                "pinyin": "Zài Shǒuhù qiānnián de lìshǐ huíxiǎng de tànsuǒ túzhōng, Mǎkè yǔ Āmèi jǐnmì pèihé, zǐxì fēnxī gǔjí yǔ shíkè de měi yí chù xìjié.",
