                "pinyin": "Suízhe tànhuǒ mànbèi de nóngyù cháxiāng zài kōngqì zhōng sànkāi, bīnlín xiāoshī de gǔlǎo jìyì zhōngyú chóngxīn huànfā shēngjī.",
